@@ -0,0 +1,200 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "layoutpresets.h"
+
+#include <KScreen/Config>
+#include <KScreen/Mode>
+#include <KScreen/Output>
+#include <KScreen/SetConfigOperation>
+
+#include <QDir>
+#include <QFile>
+#include <QFileInfo>
+#include <QJsonArray>
+#include <QJsonDocument>
+#include <QJsonObject>
+#include <QSaveFile>
+#include <QStandardPaths>
+
+#include <cmath>
+
+using namespace KScreen;
+
+namespace
+{
+QString filePath()
+{
+    return QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + QLatin1String("/kscreen/layouts.json");
+}
+
+QString outputId(const OutputPtr &output)
+{
+    return output->uuid().isEmpty() ? output->hashMd5() : output->uuid();
+}
+
+QStringList outputIds(const ConfigPtr &config)
+{
+    QStringList ids;
+    for (const OutputPtr &output : config->connectedOutputs()) {
+        ids.append(outputId(output));
+    }
+    ids.sort();
+    return ids;
+}
+
+QStringList outputIds(const QJsonObject &preset)
+{
+    QStringList ids;
+    for (const QJsonValue &output : preset[QLatin1String("outputs")].toArray()) {
+        ids.append(output[QLatin1String("id")].toString());
+    }
+    ids.sort();
+    return ids;
+}
+
+QJsonArray load()
+{
+    QFile file(filePath());
+    if (!file.open(QIODevice::ReadOnly)) {
+        return {};
+    }
+    return QJsonDocument::fromJson(file.readAll()).array();
+}
+
+void store(const QJsonArray &presets)
+{
+    QDir().mkpath(QFileInfo(filePath()).absolutePath());
+    QSaveFile file(filePath());
+    if (!file.open(QIODevice::WriteOnly)) {
+        qWarning() << "Failed to save screen layouts to" << filePath();
+        return;
+    }
+    file.write(QJsonDocument(presets).toJson());
+    file.commit();
+}
+
+// Index of the preset called name that was saved for the screens connected in config, or -1
+int indexOf(const QJsonArray &presets, const QString &name, const ConfigPtr &config)
+{
+    const QStringList ids = outputIds(config);
+    for (int i = 0; i < presets.size(); ++i) {
+        const QJsonObject preset = presets[i].toObject();
+        if (preset[QLatin1String("name")].toString() == name && outputIds(preset) == ids) {
+            return i;
+        }
+    }
+    return -1;
+}
+}
+
+QStringList LayoutPresets::names(const ConfigPtr &config)
+{
+    const QStringList ids = outputIds(config);
+    QStringList ret;
+    for (const QJsonValue &value : load()) {
+        const QJsonObject preset = value.toObject();
+        if (outputIds(preset) == ids) {
+            ret.append(preset[QLatin1String("name")].toString());
+        }
+    }
+    return ret;
+}
+
+void LayoutPresets::save(const QString &name, const ConfigPtr &config)
+{
+    QJsonArray outputs;
+    for (const OutputPtr &output : config->connectedOutputs()) {
+        QJsonObject entry{
+            {QLatin1String("id"), outputId(output)},
+            {QLatin1String("name"), output->name()},
+            {QLatin1String("enabled"), output->isEnabled()},
+            {QLatin1String("x"), output->pos().x()},
+            {QLatin1String("y"), output->pos().y()},
+            {QLatin1String("scale"), output->scale()},
+            {QLatin1String("rotation"), int(output->rotation())},
+            {QLatin1String("priority"), int(output->priority())},
+        };
+        if (const ModePtr mode = output->currentMode()) {
+            entry[QLatin1String("width")] = mode->size().width();
+            entry[QLatin1String("height")] = mode->size().height();
+            entry[QLatin1String("refreshRate")] = mode->refreshRate();
+        }
+        if (const OutputPtr source = config->output(output->replicationSource())) {
+            entry[QLatin1String("replicationSource")] = outputId(source);
+        }
+        outputs.append(entry);
+    }
+
+    QJsonArray presets = load();
+    const QJsonObject preset{{QLatin1String("name"), name}, {QLatin1String("outputs"), outputs}};
+    const int index = indexOf(presets, name, config);
+    if (index >= 0) {
+        presets[index] = preset;
+    } else {
+        presets.append(preset);
+    }
+    store(presets);
+}
+
+void LayoutPresets::remove(const QString &name, const ConfigPtr &config)
+{
+    QJsonArray presets = load();
+    const int index = indexOf(presets, name, config);
+    if (index >= 0) {
+        presets.removeAt(index);
+        store(presets);
+    }
+}
+
+SetConfigOperation *LayoutPresets::apply(const QString &name, const ConfigPtr &config)
+{
+    const QJsonArray presets = load();
+    const int index = indexOf(presets, name, config);
+    if (index < 0) {
+        return nullptr;
+    }
+
+    const ConfigPtr copy = config->clone();
+    QHash<QString, OutputPtr> outputs;
+    for (const OutputPtr &output : copy->connectedOutputs()) {
+        outputs.insert(outputId(output), output);
+    }
+
+    QMap<OutputPtr, uint32_t> priorities;
+    for (const QJsonValue &value : presets[index][QLatin1String("outputs")].toArray()) {
+        const QJsonObject entry = value.toObject();
+        const OutputPtr output = outputs.value(entry[QLatin1String("id")].toString());
+        const bool enabled = entry[QLatin1String("enabled")].toBool();
+        output->setEnabled(enabled);
+        priorities.insert(output, entry[QLatin1String("priority")].toInt());
+        if (!enabled) {
+            continue;
+        }
+
+        // Pick the mode with the saved size whose refresh rate is the closest to the saved one
+        const QSize size(entry[QLatin1String("width")].toInt(), entry[QLatin1String("height")].toInt());
+        const double refreshRate = entry[QLatin1String("refreshRate")].toDouble();
+        ModePtr bestMode;
+        for (const ModePtr &mode : output->modes()) {
+            if (mode->size() == size && (!bestMode || std::abs(mode->refreshRate() - refreshRate) < std::abs(bestMode->refreshRate() - refreshRate))) {
+                bestMode = mode;
+            }
+        }
+        if (bestMode) {
+            output->setCurrentModeId(bestMode->id());
+        }
+
+        output->setPos(QPoint(entry[QLatin1String("x")].toInt(), entry[QLatin1String("y")].toInt()));
+        output->setScale(entry[QLatin1String("scale")].toDouble(1.0));
+        output->setRotation(Output::Rotation(entry[QLatin1String("rotation")].toInt(Output::None)));
+        const OutputPtr source = outputs.value(entry[QLatin1String("replicationSource")].toString());
+        output->setReplicationSource(source ? source->id() : 0);
+    }
+    copy->setOutputPriorities(priorities);
+
+    return new SetConfigOperation(copy);
+}
